package rules

import "testing"

// Cases ported from PHP-CS-Fixer's ArrayPushFixerTest (tests/Fixer/Alias), then
// invented ones (named "extra"/"analyzer"/...); every expected output is what
// PHP-CS-Fixer 3.95 produces for the input.
func TestArrayPushPhpCsFixerCases(t *testing.T) {
	t.Parallel()
	aliasRunUpstreamCases(t, ArrayPush{}, []aliasUpstreamCase{
		{"minimal", nil, "<?php array_push($a,$b);", "<?php $a[] =$b;"},
		{"simple", nil, "<?php array_push($a, $b);", "<?php $a[] = $b;"},
		{"simple, spaces", nil, "<?php array_push( $a ,  $b );", "<?php  $a   [] =$b ;"},
		{"simple 25x times", nil, "<?php array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);array_push($a, $b);", "<?php $a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;$a[] = $b;"},
		{"simple namespaced", nil, "<?php \\array_push($a, $b1);", "<?php $a[] = $b1;"},
		{"; before", nil, "<?php ; array_push($a1, $b2) ?>", "<?php ; $a1[] = $b2 ?>"},
		{") before", nil, "<?php\n                if ($c) array_push($a, $b);\n\n                while (--$c > 0) array_push($a, $c);\n            ", "<?php\n                if ($c) $a[] = $b;\n\n                while (--$c > 0) $a[] = $c;\n            "},
		{"} before", nil, "<?php $b3 = []; { $a = 1; } \\array_push($b5, 1);", "<?php $b3 = []; { $a = 1; } $b5[] = 1;"},
		{"{ before", nil, "<?php { array_push($a, $b8); }", "<?php { $a[] = $b8; }"},
		{"comments and PHPDoc", nil, "<?php /* */ array_push($a2, $b3) /** */;", "<?php /* */ $a2[] = $b3 /** */;"},
		{"Fix#10", nil, "<?php array_push($a4[1], $b6[2]);", "<?php $a4[1][] = $b6[2];"},
		{"case insensitive and precedence", nil, "<?php\n                array_push($a, $b--);\n                ARRAY_push($a, ++$b);\n                array_PUSH($a, !$b);\n                ARRAY_PUSH($a, $b + $c);\n                \\array_push($a, 1 ** $c / 2 || !b && c(1,2,3) ^ $a[1]);\n            ", "<?php\n                $a[] = $b--;\n                $a[] = ++$b;\n                $a[] = !$b;\n                $a[] = $b + $c;\n                $a[] = 1 ** $c / 2 || !b && c(1,2,3) ^ $a[1];\n            "},
		{"simple traditional array", nil, "<?php array_push($a, array($b, $c));", "<?php $a[] = array($b, $c);"},
		{"simple short array", nil, "<?php array_push($a, [$b]);", "<?php $a[] = [$b];"},
		{"multiple element short array", nil, "<?php array_push($a, [[], [], $b, $c]);", "<?php $a[] = [[], [], $b, $c];"},
		{"second argument wrapped in `(` `)`", nil, "<?php array_push($a::$c, ($b));", "<?php $a::$c[] = ($b);"},
		{"Fix#16", nil, "<?php array_push($a::$c, $b);", "<?php $a::$c[] = $b;"},
		{"Fix#17", nil, "<?php array_push($a[foo(1,2,3)], $b[foo(1,2,3)]);", "<?php $a[foo(1,2,3)][] = $b[foo(1,2,3)];"},
		{"Fix#18", nil, "<?php array_push(\\A\\B::$foo, 1);", "<?php \\A\\B::$foo[] = 1;"},
		{"Fix#19", nil, "<?php array_push(static::$foo, 1);", "<?php static::$foo[] = 1;"},
		{"Fix#20", nil, "<?php array_push(namespace\\A::$foo, 1);", "<?php namespace\\A::$foo[] = 1;"},
		{"Fix#21", nil, "<?php array_push(foo()->bar, 1);", "<?php foo()->bar[] = 1;"},
		{"Fix#22", nil, "<?php array_push(foo(), 1);", "<?php foo()[] = 1;"},
		{"Fix#23", nil, "<?php array_push($a->$c, $b);", "<?php $a->$c[] = $b;"},
		{"Fix#24", nil, "<?php array_push($a->$c[1]->$d[$a--]->$a[7], $b);", "<?php $a->$c[1]->$d[$a--]->$a[7][] = $b;"},
		{"push multiple", nil, "<?php array_push($a6, $b9, $c);", "<?php array_push($a6, $b9, $c);"},
		{"push multiple II", nil, "<?php ; array_push($a6a, $b9->$a(1,2), $c);", "<?php ; array_push($a6a, $b9->$a(1,2), $c);"},
		{"push multiple short", nil, "<?php array_push($a6, [$b,$c], []);", "<?php array_push($a6, [$b,$c], []);"},
		{"returns number of elements in the array I", nil, "<?php foo(array_push($a7, $b10)); // ;array_push($a, $b);", "<?php foo(array_push($a7, $b10)); // ;array_push($a, $b);"},
		{"returns number of elements in the array II", nil, "<?php $a = 3 * array_push($a8, $b11);", "<?php $a = 3 * array_push($a8, $b11);"},
		{"returns number of elements in the array III", nil, "<?php $a = foo($z, array_push($a9, $b12));", "<?php $a = foo($z, array_push($a9, $b12));"},
		{"returns number of elements in the array IV", nil, "<?php $z = array_push($a00, $b13);", "<?php $z = array_push($a00, $b13);"},
		{"function declare in different namespace", nil, "<?php namespace Foo; function array_push($a11, $b14){};", "<?php namespace Foo; function array_push($a11, $b14){};"},
		{"overridden detect I", nil, "<?php namespace Foo; array_push(1, $a15);", "<?php namespace Foo; array_push(1, $a15);"},
		{"overridden detect II", nil, "<?php namespace Foo; array_push($a + 1, $a16);", "<?php namespace Foo; array_push($a + 1, $a16);"},
		{"different namespace and not a function call", nil, "<?php\n                A\\array_push($a, $b17);\n                A::array_push($a, $b18);\n                $a->array_push($a, $b19);\n            ", "<?php\n                A\\array_push($a, $b17);\n                A::array_push($a, $b18);\n                $a->array_push($a, $b19);\n            "},
		{"open echo", nil, "<?= array_push($a, $b20) ?> <?= array_push($a, $b20); ?>", "<?= array_push($a, $b20) ?> <?= array_push($a, $b20); ?>"},
		{"ellipsis", nil, "<?php array_push($a, ...$b21);", "<?php array_push($a, ...$b21);"},
		{"Fix#38", nil, "<?php\n                while (foo()) array_push($a, $b);\n                foreach (foo() as $C) array_push($a, $b);\n                if (foo()) array_push($a, $b);\n                if ($b) {} elseif (foo()) array_push($a, $b);\n            ", "<?php\n                while (foo()) $a[] = $b;\n                foreach (foo() as $C) $a[] = $b;\n                if (foo()) $a[] = $b;\n                if ($b) {} elseif (foo()) $a[] = $b;\n            "},
		{"many calls", nil, "<?php\n    array_push($a, 1);\n    array_push($a);\n    array_push($a, 2);", "<?php\n    $a[] = 1;\n    array_push($a);\n    $a[] = 2;"},
		{"expression after call", nil, "<?php array_push($a, $b) + 1;", "<?php array_push($a, $b) + 1;"},
		{"Fix80#41", nil, "<?php array_push($b?->c[2], $b19);", "<?php array_push($b?->c[2], $b19);"},
		{"simple 8.1", nil, "<?php\n                array_push($a, $b);\n                $a = array_push(...);\n            ", "<?php\n                $a[] = $b;\n                $a = array_push(...);\n            "},
		{"precedence #1", nil, "<?php array_push($a, $b and $c);", "<?php array_push($a, $b and $c);"},
		{"precedence #2", nil, "<?php array_push($a, $b or $c);", "<?php array_push($a, $b or $c);"},
		{"precedence #3", nil, "<?php array_push($a, $b xor $c);", "<?php array_push($a, $b xor $c);"},
		{"analyzer #1", nil, "<?php\nnamespace Acme;\n\nuse function Other\\array_push;\n\narray_push($list, $item);", "<?php\nnamespace Acme;\n\nuse function Other\\array_push;\n\narray_push($list, $item);"},
		{"analyzer #2", nil, "<?php\nnamespace Acme;\n\nuse function array_push;\n\narray_push($list, $item);", "<?php\nnamespace Acme;\n\nuse function array_push;\n\n$list[] = $item;"},
		{"analyzer #3", nil, "<?php\nnamespace Acme;\n\nuse function Other\\{array_push};\n\narray_push($list, $item);", "<?php\nnamespace Acme;\n\nuse function Other\\{array_push};\n\n$list[] = $item;"},
		{"analyzer #4", nil, "<?php\nnamespace Acme;\n\nuse function Other\\array_push, Other\\foo;\n\narray_push($list, $item);", "<?php\nnamespace Acme;\n\nuse function Other\\array_push, Other\\foo;\n\n$list[] = $item;"},
		{"analyzer #5", nil, "<?php\nnamespace Acme;\n\nuse function Other\\push as array_push;\n\narray_push($list, $item);", "<?php\nnamespace Acme;\n\nuse function Other\\push as array_push;\n\narray_push($list, $item);"},
		{"analyzer #6", nil, "<?php\nnamespace Acme;\n\nfunction array_push(array &$list, $item) {}\n\narray_push($list, $item);", "<?php\nnamespace Acme;\n\nfunction array_push(array &$list, $item) {}\n\narray_push($list, $item);"},
		{"analyzer #7", nil, "<?php\nfunction array_push(array &$list, $item) {}\n\narray_push($list, $item);", "<?php\nfunction array_push(array &$list, $item) {}\n\n$list[] = $item;"},
		{"analyzer #8", nil, "<?php\nnamespace A {\n    function array_push(array &$list, $item) {}\n}\n\nnamespace B {\n    array_push($list, $item);\n}", "<?php\nnamespace A {\n    function array_push(array &$list, $item) {}\n}\n\nnamespace B {\n    $list[] = $item;\n}"},
		{"analyzer #9", nil, "<?php\nnamespace A {\n    function array_push(array &$list, $item) {}\n    array_push($list, $item);\n}", "<?php\nnamespace A {\n    function array_push(array &$list, $item) {}\n    array_push($list, $item);\n}"},
		{"analyzer #10", nil, "<?php\nnamespace A;\n\nclass Box {\n    public function array_push($a, $b) {}\n}\n\narray_push($list, $item);", "<?php\nnamespace A;\n\nclass Box {\n    public function array_push($a, $b) {}\n}\n\n$list[] = $item;"},
		{"analyzer #11", nil, "<?php\nnamespace A;\n\n$f = function () use ($list) { array_push($list, 1); };", "<?php\nnamespace A;\n\n$f = function () use ($list) { $list[] = 1; };"},
		{"analyzer #12", nil, "<?php\narray_push($list, $item);\narray_push((new Box())->items, $item);\narray_push($this->items, 1);\narray_push($this?->items, 1);\narray_push(${'name'}, 1);\narray_push($$name, 1);\narray_push($obj->{'items'}, 1);\narray_push(Box::$items, 1);\narray_push([$a][0], 1);\narray_push((int) $a, 1);", "<?php\n$list[] = $item;\narray_push((new Box())->items, $item);\n$this->items[] = 1;\narray_push($this?->items, 1);\n${'name'}[] = 1;\n$$name[] = 1;\n$obj->{'items'}[] = 1;\nBox::$items[] = 1;\narray_push([$a][0], 1);\narray_push((int) $a, 1);"},
		{"analyzer #13", nil, "<?php\nif ($ok) { array_push($list, ['a' => 1, 'b' => [2, 3]]); }\nforeach ($rows as $row) array_push($out, $row);\narray_push($list, fn ($x) => $x, );\narray_push($list, $a ? $b : $c);\narray_push($list, yield $x);", "<?php\nif ($ok) { $list[] = ['a' => 1, 'b' => [2, 3]]; }\nforeach ($rows as $row) $out[] = $row;\narray_push($list, fn ($x) => $x, );\n$list[] = $a ? $b : $c;\narray_push($list, yield $x);"},
	})
}
